import{_ as e,o as a,c as o,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"1961年 · 合伙哲学奠基之年","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1961年.md","filePath":"05_quotes/by-year/1961年.md"}'),l={name:"05_quotes/by-year/1961年.md"};function u(s,t,q,h,_,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_1961年-·-合伙哲学奠基之年" tabindex="-1">1961年 · 合伙哲学奠基之年 <a class="header-anchor" href="#_1961年-·-合伙哲学奠基之年" aria-label="Permalink to &quot;1961年 · 合伙哲学奠基之年&quot;">​</a></h1><blockquote><p>&quot;在道指下跌25%或30%的年份，我们应该只会下跌15%到20%；没有人能确切知道这样的年份何时到来，但我认为这是极有可能发生的。&quot;——巴菲特（31岁）</p></blockquote><p>本页收录1961年致股东信中的经典语录。这一年，巴菲特系统阐述了三大投资类别（低估类、套利类、控股类）的运作逻辑，并首次明确表达了对保守主义的深层思考。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;在任何年份，我们相对于平均指数表现出的任何优异表现，可能不是在上升市场中取得的，而是在平稳或下降市场中。&quot;</p></blockquote><blockquote><p>&quot;在道指下跌25%或30%的年份，我们应该只会下跌15%到20%；没有人能确切知道这样的年份何时到来，但我认为这是极有可能发生的。&quot;</p></blockquote><blockquote><p>&quot;你不会因为大多数人暂时认同你，就站在了正确的一边；也不会因为重要人物认同你，就站在了正确的一边。但在无数次投资交易中，只有当你的假设正确、事实正确、推理正确时，你才会最终站在正确的一边。真正的保守主义，只能通过知识与理性实现。&quot;</p></blockquote><blockquote><p>&quot;真正的保守主义，只能通过知识与理性实现。&quot;</p></blockquote><blockquote><p>&quot;我认为，检验我们投资方式保守程度最客观的标准，就是看我们在下跌市场中的业绩表现，最好是道指出现大幅下跌的市场环境。&quot;</p></blockquote><blockquote><p>&quot;我们从未发生过单笔已实现亏损超过总资产0.5%或1%的情况，我们的已实现收益总额与已实现亏损总额的比例约为100:1。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1961年是丰收年，道指上涨22.2%，而合伙企业平均收益率高达45.9%。巴菲特在取得登普斯特农机制造公司控股权后，明确提出了&quot;控股类投资&quot;的理念，并警告：当前蓝筹股不看过市盈率就买入，并非保守投资，而是投机。同时宣布将合伙人最低入伙门槛从2.5万美元提高。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1961年-翻译-·-01-letters-1961年-核心总结-·-01-letters-1961年-思维导图" tabindex="-1"><a href="/01_letters/1961年/翻译.html">01_letters/1961年/翻译</a> · <a href="/01_letters/1961年/核心总结.html">01_letters/1961年/核心总结</a> · <a href="/01_letters/1961年/思维导图.html">01_letters/1961年/思维导图</a> <a class="header-anchor" href="#_01-letters-1961年-翻译-·-01-letters-1961年-核心总结-·-01-letters-1961年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1961年/翻译]] · [[→ 核心总结|01_letters/1961年/核心总结]] · [[→ 思维导图|01_letters/1961年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1961年/翻译.html">/01_letters/1961年/翻译</a></li></ul>',19)])])}const b=e(l,[["render",u]]);export{n as __pageData,b as default};
